class Solution { public:
 long long maximumValueSum(vector<vector<int>>& board){int m=board.size(),n=board[0].size();
  vector<vector<pair<long long,int>>> top(m+1),bottom(m+1);
  auto best3=[&](vector<long long>& vals){vector<pair<long long,int>> v;for(int c=0;c<n;++c)v.push_back({vals[c],c});sort(v.rbegin(),v.rend());if(v.size()>3)v.resize(3);return v;};
  vector<long long> col(n,LLONG_MIN/4);
  for(int r=0;r<m;++r){top[r]=best3(col);for(int c=0;c<n;++c)col[c]=max(col[c],(long long)board[r][c]);}
  fill(col.begin(),col.end(),LLONG_MIN/4);
  for(int r=m-1;r>=0;--r){bottom[r+1]=best3(col);for(int c=0;c<n;++c)col[c]=max(col[c],(long long)board[r][c]);}
  long long ans=LLONG_MIN;
  for(int r=1;r+1<m;++r)for(auto a:top[r])for(auto b:bottom[r+1])if(a.second!=b.second)
   for(int c=0;c<n;++c)if(c!=a.second&&c!=b.second)ans=max(ans,1LL*a.first+b.first+board[r][c]);
  return ans;
 }
};
